mapper.select:
SELECT COALESCE(SUM(gross_pay), 0) AS gross_sum,
       COUNT(*) AS months
  FROM (
    SELECT gross_pay
      FROM gw_payroll
     WHERE user_id = #{userId}
       AND status_cd IN ('CONFIRMED','PAID')
     ORDER BY pay_month DESC
     LIMIT #{months}
  ) recent

mapper.update:
UPDATE gw_severance
   SET status_cd = #{statusCd}, paid_dt = #{paidDt}
 WHERE sev_id = #{sevId}
